import{z as B,x as A,o as s,c as d,q as E,j as n,D as e,d as r,s as i,S as l,b as o}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Kurose / Ross 网络","description":"","frontmatter":{"title":"Kurose / Ross 网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kurose-ross.md","filePath":"cs/kurose-ross.md","lastUpdated":1791063341000}'),p={name:"cs/kurose-ross.md"};function u(m,a,h,c,T,D){const t=A("Mermaid");return s(),d("div",null,[a[2]||(a[2]=E('<h1 id="kurose-ross-网络" tabindex="-1">Kurose / Ross 网络 <a class="header-anchor" href="#kurose-ross-网络" aria-label="Permalink to &quot;Kurose / Ross 网络&quot;">​</a></h1><div class="epigraph"><p>自顶向下：先应用与传输合同，再下到 IP 与链路；五层是教学地图，协议细节以 RFC 与实现为准。</p><footer>—— Kurose and Ross, Computer Networking: A Top-Down Approach</footer></div><p><a href="/cs/riscv-priv-spec">上一课</a>附录对照了 RISC-V 特权手册。附录对照，不插入主干。本栏附录到此结束。主干已在<a href="/cs/layering-e2e">分层与端到端</a>到<a href="/cs/socket-api">套接字</a>按五层走过网络；这里对照 <strong>这本教材的问题</strong>：如何把互联网协议收成可教的一本，并用自顶向下挡住「先背满以太网再谈 HTTP」。不重做握手与 BGP 政策。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>特权手册给主机内部契约。Kurose/Ross 的缺口是主机之间：套接字应用看到什么，TCP/UDP 保证什么，IP 如何转发，链路如何成帧。主干课序其实是自底向上接 OS 的 DMA，与教材目录相反——这正是对照的意义：教材可以从 HTTP 讲起，本栏必须先有帧，因为上一门课是 virtio 与 DMA。RFC 791/793/8200 在主干当真实编号使用，教材是地图不是标准文本。</p><p><span class="marginnote">Tanenbaum <em>Computer Networks</em> 是另一本对照。本栏网络课多次点名 Kurose and Ross，与 MOS 那本 OS 教材分工：一个协议栈，一个内核子系统。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>教材分应用、传输、网络、链路，加无线与多媒体等章。主干把 CDN、任播、拥塞算法拆进课序叶子，不把某年版的「历史上的 HTTP」插进主干。附录对照方法：顶层合同先讲清，再允许读者往下看实现。</p>',8)),(s(),n(l,null,{default:e(()=>[i(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BOOK%5B%22%E8%87%AA%E9%A1%B6%E5%90%91%E4%B8%8B%E6%95%99%E6%9D%90%22%5D%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%20%2F%20%E4%BC%A0%E8%BE%93%E5%90%88%E5%90%8C%22%5D%0A%20%20BOOK%20--%3E%20IP%5B%22IP%20%2F%20%E8%B7%AF%E7%94%B1%20%2F%20%E9%93%BE%E8%B7%AF%22%5D%0A%20%20IP%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E4%BA%94%E5%B1%82%E8%87%AA%E5%BA%95%E5%90%91%E4%B8%8A%E6%8E%A5%20DMA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,"教材把 Saltzer 端到端、Cerf–Kahn 互联、RFC 字节流收成习题与抓包直觉。主干已经按树上课；读这本书不能替代从帧读到套接字。安全课的 TLS 在教材里常单章，本栏放在安全主干用 RFC 8446。",-1)),(s(),n(l,null,{default:e(()=>[i(t,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E4%BA%94%E5%B1%82%E5%9C%B0%E5%9B%BE%2C%20%E4%B8%A4%E7%A7%8D%E8%B5%B0%E6%B3%95%22%5D%20--%3E%20TD%5B%22%E6%95%99%E6%9D%90%3A%20%E8%87%AA%E9%A1%B6%E5%90%91%E4%B8%8B%22%5D%0A%20%20Q%20--%3E%20BU%5B%22%E6%9C%AC%E6%A0%8F%E4%B8%BB%E5%B9%B2%3A%20%E8%87%AA%E5%BA%95%E5%90%91%E4%B8%8A%22%5D%0A%20%20TD%20--%3E%20T1%5B%22%E5%85%88%20HTTP%20%E4%B8%8E%E5%A5%97%E6%8E%A5%E5%AD%97%E5%90%88%E5%90%8C%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E5%86%8D%20TCP%20%2F%20IP%20%2F%20%E9%93%BE%E8%B7%AF%22%5D%0A%20%20BU%20--%3E%20B1%5B%22%E5%85%88%E5%B8%A7%E4%B8%8E%20DMA%22%5D%0A%20%20B1%20--%3E%20B2%5B%22%E5%86%8D%20IP%20%2F%20TCP%20%2F%20%E5%BA%94%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=E('<p><span class="marginnote">直觉类比：五层像一栋楼——自顶向下是先逛顶层餐厅、再下到地基看水电管线；自底向上是先验收管线、再逐层往上开张。两种顺序看到的是同一栋楼，本栏选后者只因上一门课刚讲完 DMA。</span></p><p><span class="marginnote">术语翻译：RFC 就是「互联网协议的原始法律文本」——RFC 791 写 IP、793 写 TCP、8446 写 TLS 1.3。教材是导游图，把法条翻译成可读的路线；抓包核对字段时，最终还是要回到 RFC 对原文。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若把 Kurose/Ross 插在特权手册之后当「必读下一课」，课序会变成另一本教材目录，并且与已上完的网络课重复。附录只对照地图与自顶向下立场。主干封口仍是<a href="/cs/to-systems-boundary">计算栈到此为止</a>。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把课后编程作业当本栏叶子。也不要在附录里开 SDN 控制器型号审计。计算机栏主干已封口；本附录结束文献序列，不把读者送回比特课，只送回那张协议地图。</p><p>对照结束应回到主干网络各课与<a href="/cs/to-systems-boundary">计算栈到此为止</a>。文献序列在此终止。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Kurose and Ross：自顶向下的互联网教材地图。</li><li>主干网络课已按五层取用；RFC 791/793/8200/8446 是标准，教材是地图。</li><li>文献对照序列在此结束；主干封口仍是 to-systems-boundary。</li><li>出处：Kurose and Ross, <em>Computer Networking</em>。</li></ul>',9))])}const f=B(p,[["render",u]]);export{P as __pageData,f as default};
